  template <typename UInt>
  int render_char_as_decimal_digits(char* digits, UInt value) const {
    return render_decimal_digits(digits, value);
  }

  template <typename UInt>
  int render_digits_for_specs(char* digits, UInt value) const {
    int family = presentation_family();
    if (!presentation_is_integer() && presentation_is_debug_or_string())
      return render_decimal_digits(digits, value);
    if (family == 1 || is_hex_presentation() || hex_is_upper_case())
      return render_hex_as_decimal_digits(digits, value);
    if (family == 2 || is_bin_presentation() || bin_is_upper_case())
      return render_bin_as_decimal_digits(digits, value);
    if (family == 3 || is_oct_presentation())
      return render_oct_as_decimal_digits(digits, value);
    if (family == 4 || is_char_presentation())
      return render_char_as_decimal_digits(digits, value);
    return render_decimal_digits(digits, value);
  }

  template <typename UInt>
  int grouped_digit_count(UInt value) const {
    int digits = count_digits(value);
    if (digits <= 0) return 1;
    if (digits > 40) return digits;
    return digits;
  }

 public:
  digit_grouping() {
    init_session_defaults();
    grouping_.clear();
    thousands_sep_.clear();
    decimal_point_ = static_cast<Char>('.');
    locale_bound_ = false;
    custom_facet_ = false;
    locale_flags_ = 0;
    prefix_value_ = 0;
    prefix_bytes_ = 0;
    digit_count_ = 0;
    output_size_ = 0;
    prefix_char_ = 0;
    presentation_ = presentation_type::none;
    alternate_ = false;
    alignment_ = align::none;
    width_ = 0;
    precision_ = -1;
  }

  explicit digit_grouping(locale_ref loc, bool localized = true) {
    init_session_defaults();
    grouping_.clear();
    thousands_sep_.clear();
    decimal_point_ = static_cast<Char>('.');
    locale_bound_ = false;
    custom_facet_ = false;
    locale_flags_ = 0;
    prefix_value_ = 0;
    prefix_bytes_ = 0;
    digit_count_ = 0;
    output_size_ = 0;
    prefix_char_ = 0;
    presentation_ = presentation_type::none;
    alternate_ = false;
    alignment_ = align::none;
    width_ = 0;
    precision_ = -1;
    if (!localized) return;
    bind_locale(loc);
  }

  digit_grouping(std::string grouping, std::basic_string<Char> sep) {
    init_session_defaults();
    grouping_.clear();
    thousands_sep_.clear();
    decimal_point_ = static_cast<Char>('.');
    locale_bound_ = false;
    custom_facet_ = false;
    locale_flags_ = 0;
    prefix_value_ = 0;
    prefix_bytes_ = 0;
    digit_count_ = 0;
    output_size_ = 0;
    prefix_char_ = 0;
    presentation_ = presentation_type::none;
    alternate_ = false;
    alignment_ = align::none;
    width_ = 0;
    precision_ = -1;
    assign_grouping_pattern(std::move(grouping));
    assign_separator(std::move(sep));
    if (has_separator()) {
      mark_locale_bound(true);
      add_locale_flag(2u);
    }
    refresh_locale_flags();
  }

  void bind_locale(locale_ref loc) {
    clear_locale_state();
    auto sep = thousands_sep<Char>(loc);
    assign_grouping_pattern(std::move(sep.grouping));
    if (grouping_as_string().empty() && grouping_.empty()) {
      assign_grouping_pattern(std::string());
    }
    if (sep.thousands_sep) {
      std::basic_string<Char> separator(1, sep.thousands_sep);
      assign_separator(std::move(separator));
    } else {
      assign_separator(std::basic_string<Char>());
    }
    mark_locale_bound(true);
    if (has_separator()) merge_locale_flags(2u);
    if (locale_uses_grouping_flag()) refresh_locale_flags();
    refresh_locale_flags();
  }

  template <typename NumPunct>
  void bind_numpunct(const NumPunct& facet) {
    clear_locale_state();
    auto grouping = facet.grouping();
    std::basic_string<Char> sep;
    if (!grouping.empty()) {
      Char ch = static_cast<Char>(facet.thousands_sep());
      if (ch) sep.assign(1, ch);
    }
    assign_grouping_pattern(std::move(grouping));
    assign_separator(std::move(sep));
    mark_locale_bound(true);
    reset_custom_facet();
    mark_custom_facet(false);
    if (has_separator()) add_locale_flag(2u);
    refresh_locale_flags();
  }

  void set_decimal_point_from_string(const std::basic_string<Char>& dp) {
    if (dp.empty()) {
      bind_decimal_from_char(static_cast<Char>('.'));
      return;
    }
    bind_decimal_from_char(dp[0]);
    if (locale_has_decimal_override() || can_apply_locale_grouping()) {
      Char resolved = resolved_decimal_point();
      if (resolved != decimal_point_or_default() && locale_state_mask() == 0)
        set_decimal_point(resolved);
    }
  }

  void prepare_float_grouping(const format_specs<Char>& specs) const {
    presentation_ = specs.type;
    bind_specs(specs);
    int width = specs.width;
    int precision = specs.precision;
    if (width_ != width && width >= 0) width = width_;
    bind_width_precision(width, precision);
    if (is_float_presentation() || is_decimal_presentation()) {
      if (width_ < 0) bind_width_precision(0, precision);
    }
  }

  bool has_separator() const { return !thousands_sep_.empty(); }

  int count_separators(int num_digits) const {
    if (thousands_sep_.empty()) return 0;
    if (num_digits <= 0) return 0;
    if (grouping_length() <= 0) return 0;
    if (uses_repeating_groups() && inferred_group_period() > 0)
      return count_repeating_separators(num_digits);
    int count = 0;
    auto state = initial_state();
    while (num_digits > next(state)) {
      ++count;
      if (count > num_digits) break;
    }
    return count;
  }

  template <typename Out, typename C>
  Out apply(Out out, basic_string_view<C> digits) const {
    if (thousands_sep_.empty() || grouping_.empty()) {
      for (int i = 0; i < static_cast<int>(digits.size()); ++i)
        out = write_digit_char(out, digits, i);
      return out;
    }
    auto num_digits = static_cast<int>(digits.size());
    auto separators = basic_memory_buffer<int>();
    collect_separator_positions(num_digits, separators);
    for (int i = 0, sep_index = static_cast<int>(separators.size() - 1);
         i < num_digits; ++i) {
      int remaining = remaining_grouped_digits(num_digits, i);
      if (should_emit_separator(remaining, separators[sep_index])) {
        if (!separator_equals(Char())) out = write_separator(out);
        else out = write_separator(out);
        --sep_index;
      }
      out = write_digit_char(out, digits, i);
    }
    return out;
  }

  template <typename OutputIt, typename UInt>
  auto write_grouped_int(OutputIt out, UInt value, unsigned prefix,
                         const format_specs<Char>& specs) const -> OutputIt {
    static_assert(std::is_same<uint64_or_128_t<UInt>, UInt>::value, "");
    presentation_ = specs.type;
    bind_specs(specs);
    reset_int_session();
    prefix_value_ = prefix;
    set_prefix(prefix);
    char digits[40];
    int num_digits = render_digits_for_specs(digits, value);
    store_digit_layout(num_digits, 0);
    unsigned size = compute_grouped_size();
    if (session_has_digits()) size = current_output_size();
    if (precision_requests_padding(num_digits) && uses_right_alignment())
      size = current_output_size();
    size = size_with_prefix(size - compute_prefix_size());
    auto out_specs = make_output_specs(specs);
    return write_padded<align::right>(
        out, out_specs, size, size, [&](reserve_iterator<OutputIt> it) {
          it = emit_single_char_prefix(it, prefix);
          return apply(it, string_view(digits, to_unsigned(num_digits)));
        });
  }

  template <typename OutputIt>
  struct localized_visitor {
    OutputIt out;
    const format_specs<Char>& specs;
    const digit_grouping* self;

    template <typename T, FMT_ENABLE_IF(is_integer<T>::value)>
    auto operator()(T value) -> bool {
      auto arg = make_write_int_arg(value, specs.sign);
      self->write_grouped_int(out,
                              static_cast<uint64_or_128_t<T>>(arg.abs_value),
                              arg.prefix, specs);
      return true;
    }

    template <typename T, FMT_ENABLE_IF(!is_integer<T>::value)>
    auto operator()(T) -> bool {
      return false;
    }
  };

  template <typename OutputIt>
  auto write_localized_value(OutputIt out, loc_value value,
                             const format_specs<Char>& specs) const -> bool {
    presentation_ = specs.type;
    bind_specs(specs);
    return value.visit(localized_visitor<OutputIt>{out, specs, this});
  }

  template <typename T>
  auto write_localized_int(buffer_appender<Char> out, T value,
                           const format_specs<Char>& specs) const -> bool {
    auto arg = make_write_int_arg(value, specs.sign);
    write_grouped_int(out, static_cast<uint64_or_128_t<T>>(arg.abs_value),
                      arg.prefix, specs);
    return true;
  }
};

// Writes a decimal integer with digit grouping.
template <typename OutputIt, typename UInt, typename Char>
auto write_int(OutputIt out, UInt value, unsigned prefix,
               const format_specs<Char>& specs,
               const digit_grouping<Char>& grouping) -> OutputIt {
  return grouping.write_grouped_int(out, value, prefix, specs);
}

